}
public Topology() {
    foreach (string line in File.ReadAllLines("input/topology.txt", Encoding.ASCII)) {
        string[] f = line.Split(' ');
        if (f[0] == "AS")
            routerIds[int.Parse(f[1])] = AddressValue(f[2]);
        else if (f[0] == "LINK") {
            Link link = new(links.Count, f);
            links.Add(link);
            byName[link.name] = link;
        } else
            initial.Add(
                new(int.Parse(f[1]), ParsePrefix(f[2]), f[3], Policy.Communities(f.Skip(4))));
    }
    foreach (int owner in routerIds.Keys)
        atAs[owner] = new();
    foreach (Link link in links) {
        atAs[link.first].Add(link);
        atAs[link.second].Add(link);
    }
}
public Policy() {
    foreach (string line in File.ReadAllLines("input/policies.txt", Encoding.ASCII)) {
        string[] f = line.Split(' ');
        if (f[0] == "PLIST") {
            Topology.Prefix p = Topology.ParsePrefix(f[3]);
            int low = p.length, high = p.length;
            for (int i = 4; i < f.Length; i += 2)
                if (f[i] == "GE") {
                    low = int.Parse(f[i + 1]);
                    high = 32;
                }
            for (int i = 4; i < f.Length; i += 2)
                if (f[i] == "LE")
                    high = int.Parse(f[i + 1]);
            if (!lists.TryGetValue(f[1], out List<Entry> entries)) {
                entries = new();
                lists[f[1]] = entries;
            }
            entries.Add(new(f[2] == "PERMIT", p, low, high));
            continue;
        }
        int separator = Array.IndexOf(f, "THEN");
        List<Condition> conditions = new();
        for (int i = 6; i < separator; i += 2) {
            string kind = f[i], value = f[i + 1];
            int low = 0, high = 0;
            Community comm = null;
            if (kind == "CONTAINS" || kind == "ORIGINAS")
                low = int.Parse(value);
            else if (kind == "LENGTH") {
                string[] bounds = value.Split('-');
                low = int.Parse(bounds[0]);
                high = int.Parse(bounds[1]);
            } else if (kind == "COMMUNITY")
                comm = ParseCommunity(value);
            conditions.Add(new(kind, value, low, high, comm));
        }
        List<Action> actions = new();
        for (int i = separator + 1; i < f.Length;) {
            string kind = f[i++];
            int value = 0;
            Community comm = null;
            if (kind != "DENY" && kind != "ALLOW") {
                string text = f[i++];
                if (kind == "ADD" || kind == "REMOVE")
                    comm = ParseCommunity(text);
                else
                    value = int.Parse(text);
            }
            actions.Add(new(kind, value, comm));
        }
        Rule rule = new(f, conditions, actions);
        rules.Add(rule);
        byName[rule.name] = rule;
    }
}
public bool Matches(Rule rule, int owner, Topology.Link link, Topology.Prefix prefix,
                    List<int> path, List<Community> communities) {
    if (!rule.active || rule.owner != owner)
        return false;
    if (rule.target != "*" && rule.target != link.Other(owner).ToString() &&
        rule.target != link.name)
        return false;
    foreach (Condition c in rule.conditions) {
        bool match =
            c.kind switch { "PREFIX" => Permitted(c.text, prefix),
                            "CONTAINS" => path.Contains(c.low),
                            "ORIGINAS" => (path.Count == 0 ? owner : path[^1]) == c.low,
                            "LENGTH" => c.low <= path.Count && path.Count <= c.high,
                            _ => communities.Contains(c.community) };
        if (!match)
            return false;
    }
    return true;
}
public Rule Applied(string direction, int owner, Topology.Link link, Topology.Prefix prefix,
                    List<int> path, List<Community> communities) =>
    rules.FirstOrDefault(rule => rule.direction == direction &&
                                 Matches(rule, owner, link, prefix, path, communities));
public static List<Community> Edit(List<Community> communities, Rule rule) {
    SortedSet<Community> result = new(communities);
    foreach (Action action in rule.actions)
        if (action.kind == "ADD")
            result.Add(action.community);
        else if (action.kind == "REMOVE")
            result.Remove(action.community);
    return result.ToList();
}
    public Message Send(int time, int sender, int receiver, Topology.Link link,
                        Topology.Prefix prefix, Decision.Attribute content) {
        Message message =
            new(++serial, sender, receiver, link, prefix, content, time + link.delay);
        queue.Add(message);
        return message;
    }
public static List<Event> Events() {
    List<Event> events = new() { new(0, "INITIAL") };
    foreach (string line in File.ReadAllLines("input/events.txt", Encoding.ASCII)) {
        int separator = line.IndexOf(' ');
        events.Add(new(int.Parse(line[..separator]), line[(separator + 1)..]));
    }
    return events;
}
public static Params ReadParams() {
    string[] lines = File.ReadAllLines("input/params.txt", Encoding.ASCII),
             f = lines[0].Split(' ');
    Dictionary<string, int> defaults = new() { { "customer", int.Parse(f[1]) },
                                               { "peer", int.Parse(f[2]) },
                                               { "provider", int.Parse(f[3]) } };
    int stepcap = int.Parse(lines[1].Split(' ')[1]);
    List<Trace> traces = new();
    foreach (string line in lines.Skip(2)) {
        string[] t = line.Split(' ');
        traces.Add(new(int.Parse(t[1]), t[2], Topology.AddressValue(t[2])));
    }
    return new(defaults, stepcap, traces);
}
